251: func (c *controller) reconcileLease(ctx context.Context, item *lease) error {
252: 	requestedNamespace := stringValue(item.Spec["namespaceName"])
253: 	namespaceName := c.normalizeLeaseNamespaceName(requestedNamespace)
254: 	if item.Metadata.DeletionTimestamp != "" {
255: 		if !contains(item.Metadata.Finalizers, c.finalizer) {
256: 			return nil
257: 		}
258: 		if stringValue(item.Status["phase"]) == "Rejected" && stringValue(item.Status["namespaceName"]) == "" {
259: 			return c.removeFinalizer(ctx, item)
260: 		}
261: 		ownedNamespace := firstNonEmpty(stringValue(item.Status["namespaceName"]), namespaceName)
262: 		return c.reconcileDeletedLease(ctx, item, ownedNamespace)
263: 	}
264: 	if namespaceName == "" || !c.hasAllowedPrefix(namespaceName) {
265: 		return c.patchLeaseStatus(ctx, item, map[string]interface{}{
266: 			"phase":         "Rejected",
267: 			"namespaceName": nullableString(requestedNamespace),
268: 			"message":       "namespaceName must normalize to a valid broker-owned namespace",
269: 		})
270: 	}
271: 	current, err := c.ensureFinalizer(ctx, item)
272: 	if err != nil {
273: 		return err
274: 	}
275: 	item = current
276: 	if len(interfaceSlice(item.Spec["access"])) == 0 {
277: 		owned, err := c.legacyNamespaceOwned(ctx, item, namespaceName)
278: 		if err != nil {
279: 			return err
280: 		}
281: 		if owned {
282: 			if err := c.deleteLegacyRunnerAccess(ctx, namespaceName); err != nil {
283: 				return err
284: 			}
285: 		}
286: 		if expired, err := c.expireLease(ctx, item, namespaceName); expired || err != nil {
287: 			return err
288: 		}
289: 		return c.patchLeaseStatus(ctx, item, map[string]interface{}{
290: 			"phase": "Failed", "namespaceName": namespaceName,
291: 			"expiresAt": c.expiresAt(item).Format(time.RFC3339),
292: 			"message":   "Legacy lease cannot provision new work; delete it or wait for TTL cleanup",
293: 		})
294: 	}
295: 	if expired, err := c.expireLease(ctx, item, namespaceName); expired || err != nil {
296: 		return err
297: 	}
298: 
299: 	if err := c.validateLeaseSpec(item); err != nil {
300: 		if stringValue(item.Status["specDigest"]) != "" {
301: 			if deleteErr := c.deleteOwnedNamespace(ctx, item, namespaceName); deleteErr != nil {
302: 				return deleteErr
303: 			}
304: 		}
305: 		return c.patchLeaseStatus(ctx, item, rejectedStatus(namespaceName, err.Error()))
306: 	}
307: 	if digest := stringValue(item.Status["specDigest"]); digest != "" && digest != leaseSpecDigest(item.Spec) {
308: 		if stringValue(item.Status["phase"]) != "Ready" || !legacyMutableExposureDigest(digest, item.Spec) {
309: 			return c.patchLeaseStatus(ctx, item, rejectedStatus(namespaceName, "lease spec is immutable after provisioning"))
310: 		}
311: 	}
312: 
313: 	if stringValue(item.Status["phase"]) == "Ready" {
314: 		return c.reconcileReadyLease(ctx, item, namespaceName)
315: 	}
316: 	return c.provisionLease(ctx, item, namespaceName)
317: }
