319: func (c *controller) expireLease(ctx context.Context, item *lease, namespaceName string) (bool, error) {
320: 	deadline := c.expiresAt(item)
321: 	if !time.Now().After(deadline) {
322: 		return false, nil
323: 	}
324: 	if stringValue(item.Status["phase"]) == "Expired" {
325: 		return true, c.deleteOwnedNamespace(ctx, item, namespaceName)
326: 	}
327: 	if err := c.patchLeaseStatus(ctx, item, map[string]interface{}{
328: 		"phase":         "Expired",
329: 		"namespaceName": namespaceName,
330: 		"message":       "Lease TTL expired; deleting broker-owned namespace",
331: 	}); err != nil {
332: 		return true, err
333: 	}
334: 	return true, c.deleteOwnedNamespace(ctx, item, namespaceName)
335: }
