337: func (c *controller) reconcileReadyLease(ctx context.Context, item *lease, namespaceName string) error {
338: 	if err := c.verifyNamespaceOwnership(ctx, item, namespaceName); err != nil {
339: 		return err
340: 	}
341: 	if err := c.ensureBusterE2EEgressPolicy(ctx, item, namespaceName); err != nil {
342: 		return err
343: 	}
344: 	credentials, err := c.ensureTestCredentials(ctx, item, namespaceName)
345: 	if err != nil {
346: 		return err
347: 	}
348: 	exposure, err := c.ensurePreviewExposure(ctx, item, namespaceName)
349: 	if err != nil {
350: 		return err
351: 	}
352: 	for key, value := range credentials {
353: 		exposure[key] = value
354: 	}
355: 	runtimeSecurity := objectValue(item.Status["runtimeSecurity"])
356: 	if runtimeSecurityRefreshDue(runtimeSecurity, time.Now().UTC()) {
357: 		var err error
358: 		runtimeSecurity, err = c.runtimeSecurityStatus(ctx, item, namespaceName)
359: 		if err != nil {
360: 			return err
361: 		}
362: 	}
363: 	digest := leaseSpecDigest(item.Spec)
364: 	if !exposureChanged(item.Status, exposure) && stringValue(item.Status["specDigest"]) == digest &&
365: 		runtimeSecurityStatusEqual(item.Status["runtimeSecurity"], runtimeSecurity) {
366: 		return nil
367: 	}
368: 	next := copyStatusWithoutCredentials(item.Status)
369: 	next["specDigest"] = digest
370: 	for key, value := range exposure {
371: 		next[key] = value
372: 	}
373: 	next["runtimeSecurity"] = runtimeSecurity
374: 	credentialsReady := boolValue(next["credentialsAvailable"]) || stringValue(next["credentialsRef"]) == ""
375: 	exposureReady := stringValue(next["exposurePhase"]) == "Ready" || stringValue(next["exposurePhase"]) == "Off"
376: 	next["conditions"] = []interface{}{
377: 		leaseCondition("NamespaceReady", true, "Created"),
378: 		leaseCondition("AccessReady", true, "Bound"),
379: 		leaseCondition("SecretsReady", true, "Copied"),
380: 		leaseCondition("CredentialsReady", credentialsReady, ternaryString(credentialsReady, "Available", "Pending")),
381: 		leaseCondition("ExposureReady", exposureReady, ternaryString(exposureReady, "Available", "Pending")),
382: 	}
383: 	return c.patchLeaseStatus(ctx, item, next)
384: }
