1442: func (c *controller) deleteOwnedNamespace(ctx context.Context, item *lease, namespaceName string) error {
1443: 	if err := c.fenceNamespaceCleanup(ctx, item); err != nil {
1444: 		return err
1445: 	}
1446: 	if namespaceName == "" || !c.hasAllowedPrefix(namespaceName) {
1447: 		return fmt.Errorf("refusing to delete invalid broker namespace %q", namespaceName)
1448: 	}
1449: 	var namespace map[string]interface{}
1450: 	err := c.kube(ctx, http.MethodGet, "/api/v1/namespaces/"+namespaceName, nil, "application/json", &namespace)
1451: 	if err != nil {
1452: 		var apiErr *apiError
1453: 		if errors.As(err, &apiErr) && apiErr.statusCode == http.StatusNotFound {
1454: 			return c.deleteBusterE2EEgressPolicy(ctx, item)
1455: 		}
1456: 		return err
1457: 	}
1458: 	labels := stringMap(objectValue(namespace["metadata"])["labels"])
1459: 	legacyOwned := len(interfaceSlice(item.Spec["access"])) == 0 &&
1460: 		labels["kubeclaw/buster-lease-uid"] == ""
1461: 	if labels["kubeclaw/managed-by"] != "buster-namespace-controller" ||
1462: 		labels["kubeclaw/buster-lease"] != leaseLabelValue(item) ||
1463: 		(!legacyOwned && labels["kubeclaw/buster-lease-uid"] != item.Metadata.UID) {
1464: 		return fmt.Errorf("%w: refusing to delete namespace %s", errNamespaceOwnershipMismatch, namespaceName)
1465: 	}
1466: 	if err := c.deleteBusterE2EEgressPolicy(ctx, item); err != nil {
1467: 		return err
1468: 	}
1469: 	return c.deleteNamespaceCAS(ctx, namespaceName, namespace)
1470: }
