1472: func (c *controller) waitForNamespaceDeleted(ctx context.Context, namespaceName string) error {
1473: 	deadline := time.Now().Add(2 * time.Minute)
1474: 	for time.Now().Before(deadline) {
1475: 		err := c.kube(ctx, http.MethodGet, "/api/v1/namespaces/"+namespaceName, nil, "application/json", nil)
1476: 		if err != nil {
1477: 			var apiErr *apiError
1478: 			if errors.As(err, &apiErr) && apiErr.statusCode == http.StatusNotFound {
1479: 				return nil
1480: 			}
1481: 			return err
1482: 		}
1483: 		time.Sleep(c.pollInterval)
1484: 	}
1485: 	return fmt.Errorf("namespace %s was not deleted before cleanup timeout", namespaceName)
1486: }

1580: func (c *controller) expiresAt(item *lease) time.Time {
1581: 	if deadline, ok := demoReadyDeadline(item); ok {
1582: 		return productDeadline(item, deadline)
1583: 	}
1584: 	ttl := c.defaultTTL
1585: 	if value := intValue(item.Spec["ttlSeconds"], 0); value > 0 {
1586: 		ttl = time.Duration(value) * time.Second
1587: 	}
1588: 	if c.maxTTL > 0 && ttl > c.maxTTL {
1589: 		ttl = c.maxTTL
1590: 	}
1591: 	createdAt, err := time.Parse(time.RFC3339, item.Metadata.CreationTimestamp)
1592: 	if err != nil {
1593: 		createdAt = time.Now()
1594: 	}
1595: 	return createdAt.Add(ttl)
1596: }
