202: func (c *controller) commitDemoReady(ctx context.Context, r demoReadyRequest) (map[string]interface{}, error) {
203: 	if !readyDigest.MatchString(r.wireDigest) {
204: 		return nil, errors.New("DEMO_READY_REQUEST_INVALID")
205: 	}
206: 	var item lease
207: 	if err := c.kube(ctx, http.MethodGet, c.leasePath(r.LeaseName), nil, "application/json", &item); err != nil {
208: 		return nil, err
209: 	}
210: 	if item.Metadata.UID != r.LeaseUID || item.Metadata.ResourceVersion == "" || stringValue(item.Status["phase"]) != "Ready" {
211: 		return nil, errors.New("DEMO_READY_LEASE_NOT_CURRENT")
212: 	}
213: 	if item.Metadata.DeletionTimestamp != "" {
214: 		return nil, errors.New("DEMO_READY_LEASE_DELETING")
215: 	}
216: 	if !time.Now().Before(c.expiresAt(&item)) {
217: 		return nil, errors.New("DEMO_READY_EXPIRED")
218: 	}
219: 	state := objectValue(item.Status["demoReadiness"])
220: 	if len(state) > 0 {
221: 		if state["requestDigest"] != readyRequestDigest(r) || state["state"] != "ready-for-acceptance" {
222: 			receipt := objectValue(state["receipt"])
223: 			if receipt["messageId"] != r.Receipt.MessageID || receipt["deliveryId"] != r.Receipt.DeliveryID || receipt["payloadDigest"] != r.Receipt.PayloadDigest || receipt["target"] != r.Receipt.Target {
224: 				return nil, errors.New("DEMO_READY_RECEIPT_CONFLICT")
225: 			}
226: 			return nil, errors.New("DEMO_READY_REPLAY_CHANGED")
227: 		}
228: 		if err := c.verifyCommittedReady(ctx, &item); err != nil {
229: 			return nil, err
230: 		}
231: 		return readyResponse(&item, state), nil
232: 	}
233: 	if len(objectValue(item.Status["exposureMutation"])) > 0 {
234: 		return nil, errors.New("DEMO_READY_EXPOSURE_OPERATION_UNRESOLVED")
235: 	}
236: 	observed, err := time.Parse(time.RFC3339Nano, r.ObservedAt)
237: 	now := time.Now().UTC()
238: 	if err != nil || observed.After(now) || now.Sub(observed) > 5*time.Minute {
239: 		return nil, errors.New("DEMO_READY_OBSERVATION_STALE")
240: 	}
241: 	if err = c.verifyReadySource(ctx, &item, r); err != nil {
242: 		return nil, err
243: 	}
244: 	now = time.Now().UTC()
245: 	if !now.Before(c.expiresAt(&item)) || now.Sub(observed) > 5*time.Minute {
246: 		return nil, errors.New("DEMO_READY_EXPIRED")
247: 	}
248: 	seconds, err := parseDemoRetention(r.RetentionSeconds)
249: 	if err != nil {
250: 		return nil, err
251: 	}
252: 	expires, err := demoRetentionDeadline(now, seconds)
253: 	if err != nil {
254: 		return nil, err
255: 	}
256: 	state = map[string]interface{}{"retentionSeconds": seconds, "namespace": r.Namespace, "schemaVersion": "demo-readiness.v2", "state": "ready-for-acceptance", "requestId": r.RequestID, "requestDigest": readyRequestDigest(r), "readyAt": now.Format(time.RFC3339Nano), "expiresAt": expires.Format(time.RFC3339Nano), "runId": r.RunID, "sourceRevision": r.SourceRevision, "candidateDigest": r.CandidateDigest, "decisionDigest": r.DecisionDigest, "resultDigest": r.ResultDigest, "leaseUID": r.LeaseUID, "immutableImage": r.ImmutableImage, "manifestDigest": r.ManifestDigest, "credentialDigest": r.CredentialDigest, "secretUID": r.SecretUID, "url": r.URL, "previousOwner": r.ExposureOwner, "owner": "ready:" + readyRequestDigest(r), "exposureGeneration": r.ExposureGeneration, "exposureSpec": item.Spec["exposure"], "receipt": r.Receipt}
257: 	patch := map[string]interface{}{"metadata": map[string]interface{}{"resourceVersion": item.Metadata.ResourceVersion}, "status": map[string]interface{}{"demoReadiness": state, "expiresAt": state["expiresAt"], "exposureOwner": state["owner"]}}
258: 	if err = c.kube(ctx, http.MethodPatch, c.statusPath(r.LeaseName), patch, "application/merge-patch+json", nil); err != nil {
259: 		var apiErr *apiError
260: 		if errors.As(err, &apiErr) && apiErr.statusCode == 409 {
261: 			return nil, errors.New("DEMO_READY_VERSION_CONFLICT")
262: 		}
263: 		return nil, errors.New("DEMO_READY_COMMIT_UNCERTAIN")
264: 	}
265: 	var persisted lease
266: 	if err := c.kube(ctx, http.MethodGet, c.leasePath(r.LeaseName), nil, "application/json", &persisted); err != nil {
267: 		return nil, errors.New("DEMO_READY_COMMIT_UNCERTAIN")
268: 	}
269: 	actual := objectValue(persisted.Status["demoReadiness"])
270: 	actualSeconds, retentionErr := storedDemoRetention(actual)
271: 	if _, present := actual["retentionSeconds"]; !present || retentionErr != nil || actualSeconds != seconds {
272: 		return nil, errors.New("DEMO_READY_COMMIT_UNCERTAIN")
273: 	}
274: 	if persisted.Metadata.UID != item.Metadata.UID || persisted.Metadata.DeletionTimestamp != "" || actual["requestDigest"] != state["requestDigest"] || actual["readyAt"] != state["readyAt"] || actual["expiresAt"] != state["expiresAt"] {
275: 		return nil, errors.New("DEMO_READY_COMMIT_UNCERTAIN")
276: 	}
277: 	if err := c.verifyCommittedReady(ctx, &persisted); err != nil {
278: 		return nil, err
279: 	}
280: 	return readyResponse(&persisted, actual), nil
281: }
