283: func (c *controller) verifyReadySource(ctx context.Context, item *lease, r demoReadyRequest) error {
284: 	if item.Metadata.Annotations[exposureOwnerAnnotation] != r.ExposureOwner || stringValue(item.Status["exposureOwner"]) != r.ExposureOwner {
285: 		return errors.New("DEMO_READY_EXPOSURE_OWNER_CHANGED")
286: 	}
287: 	if stringValue(item.Spec["purpose"]) != "final-preview" || stringValue(item.Spec["cleanupPolicy"]) != "retain" || stringValue(item.Status["namespaceName"]) != r.Namespace || stringValue(item.Spec["verifiedImage"]) != r.ImmutableImage || stringValue(item.Spec["manifestDigest"]) != r.ManifestDigest || stringValue(item.Status["previewUrl"]) != r.URL || stringValue(item.Status["exposurePhase"]) != "Ready" || item.Metadata.Generation != r.ExposureGeneration || item.Metadata.Annotations[exposureOwnerAnnotation] != r.ExposureOwner || stringValue(item.Status["exposureOwner"]) != r.ExposureOwner || intValue(item.Status["exposureGeneration"], 0) != int(r.ExposureGeneration) {
288: 		return errors.New("DEMO_READY_SOURCE_CHANGED")
289: 	}
290: 	var pending map[string]interface{}
291: 	if json.Unmarshal([]byte(item.Metadata.Annotations["kubeclaw.forgestack.ai/readiness-handoff"]), &pending) != nil || pending["phase"] != "awaiting-readiness" || pending["owner"] != r.ExposureOwner || pending["leaseUID"] != r.LeaseUID || pending["immutableImage"] != r.ImmutableImage || pending["manifestDigest"] != r.ManifestDigest {
292: 		return errors.New("DEMO_READY_HANDOFF_INVALID")
293: 	}
294: 	if err := c.verifyReadyNamespace(ctx, item, r.Namespace); err != nil {
295: 		return err
296: 	}
297: 	if err := c.verifyReadyIngress(ctx, item, r.Namespace, r.URL); err != nil {
298: 		return err
299: 	}
300: 	return c.verifyReadySecret(ctx, item, r.Namespace, r.SecretUID, r.CredentialDigest)
301: }

