82: func (c *controller) patchLeaseStatus(ctx context.Context, item *lease, status map[string]interface{}) error {
83: 	var current lease
84: 	if err := c.kube(ctx, http.MethodGet, c.leasePath(item.Metadata.Name), nil, "application/json", &current); err != nil {
85: 		return err
86: 	}
87: 	if current.Metadata.ResourceVersion == "" || current.Metadata.UID != item.Metadata.UID || current.Metadata.Generation != item.Metadata.Generation || current.Metadata.DeletionTimestamp != item.Metadata.DeletionTimestamp || !readyStateEqual(item, &current) || current.Metadata.Annotations[exposureOwnerAnnotation] != item.Metadata.Annotations[exposureOwnerAnnotation] {
