89: 	}
90: 	phase := stringValue(current.Status["phase"])
91: 	if (phase == "Expired" || phase == "Deleting" || phase == "Rejected") && phase != stringValue(item.Status["phase"]) {
92: 		return errors.New("lease terminal transition superseded")
93: 	}
94: 	claim := stringValue(objectValue(current.Status["exposureMutation"])["id"])
95: 	terminal := status["phase"] == "Expired" || status["phase"] == "Deleting" || status["phase"] == "Rejected"
96: 	if claim != "" && item.ExposureClaim != claim && !terminal {
97: 		return errors.New("DEMO_READY_EXPOSURE_OPERATION_UNRESOLVED")
98: 	}
99: 	if claim != "" && (terminal || (status["exposurePhase"] != nil && status["exposurePhase"] != "Reconciling")) {
100: 		status["exposureMutation"] = nil
101: 	}
102: 	unchanged := true
103: 	for key, value := range status {
104: 		a, _ := json.Marshal(value)
105: 		b, _ := json.Marshal(current.Status[key])
106: 		if string(a) != string(b) {
107: 			unchanged = false
108: 		}
109: 	}
110: 	if unchanged {
111: 		return nil
112: 	}
113: 	if err := c.kube(ctx, http.MethodPatch, c.statusPath(item.Metadata.Name), map[string]interface{}{"metadata": map[string]interface{}{"resourceVersion": current.Metadata.ResourceVersion}, "status": status}, "application/merge-patch+json", nil); err != nil {
114: 		return err
115: 	}
116: 	if item.Status == nil {
117: 		item.Status = map[string]interface{}{}
118: 	}
119: 	for key, value := range status {
120: 		item.Status[key] = value
121: 	}
122: 	if value, exists := status["exposureMutation"]; exists && value == nil {
123: 		item.ExposureClaim = ""
124: 	}
125: 	return nil
126: }
