164: func (c *controller) fenceExposureMutation(ctx context.Context, item *lease) error {
165: 	// The CAS reservation makes readiness admission reject until the original
166: 	// reconciler publishes the newly observed exposure. A stale pre-Ready worker
167: 	// cannot delete/replace the ingress after the readiness status committed.
168: 	if item.ExposureClaim == "" {
169: 		random := make([]byte, 24)
170: 		if _, err := rand.Read(random); err != nil {
171: 			return err
172: 		}
173: 		item.ExposureClaim = hex.EncodeToString(random)
174: 	}
175: 	if err := c.patchLeaseStatus(ctx, item, map[string]interface{}{"exposurePhase": "Reconciling", "exposureMutation": map[string]interface{}{"id": item.ExposureClaim, "startedAt": time.Now().UTC().Format(time.RFC3339)}}); err != nil {
176: 		return err
177: 	}
178: 	var persisted lease
179: 	if err := c.kube(ctx, http.MethodGet, c.leasePath(item.Metadata.Name), nil, "application/json", &persisted); err != nil {
180: 		return err
181: 	}
182: 	if persisted.Metadata.UID != item.Metadata.UID || persisted.Metadata.DeletionTimestamp != "" || stringValue(objectValue(persisted.Status["exposureMutation"])["id"]) != item.ExposureClaim || !readyStateEqual(item, &persisted) {
183: 		return errors.New("DEMO_READY_EXPOSURE_OPERATION_UNRESOLVED")
184: 	}
185: 	return nil
186: }
