83: // Decode the exact signed bytes. Reject duplicate keys as well as unknown fields,
84: // trailing values, invalid UTF-8, and nested duplicates before typed decoding.
85: func productJSON(raw []byte, target interface{}) error {
86: 	if !utf8.Valid(raw) {
87: 		return errors.New("DEMO_PRODUCT_REQUEST_INVALID")
88: 	}
89: 	d := json.NewDecoder(bytes.NewReader(raw))
90: 	var walk func() error
91: 	walk = func() error {
92: 		token, err := d.Token()
93: 		if err != nil {
94: 			return err
95: 		}
96: 		delimiter, ok := token.(json.Delim)
97: 		if !ok {
98: 			return nil
99: 		}
100: 		switch delimiter {
101: 		case '{':
102: 			keys := map[string]bool{}
103: 			for d.More() {
104: 				token, err = d.Token()
105: 				if err != nil {
106: 					return err
107: 				}
108: 				key, ok := token.(string)
109: 				if !ok || keys[key] {
110: 					return errors.New("duplicate key")
111: 				}
112: 				keys[key] = true
113: 				if err = walk(); err != nil {
114: 					return err
115: 				}
116: 			}
117: 		case '[':
118: 			for d.More() {
119: 				if err = walk(); err != nil {
120: 					return err
121: 				}
122: 			}
123: 		default:
124: 			return errors.New("invalid delimiter")
125: 		}
126: 		_, err = d.Token()
127: 		return err
128: 	}
129: 	if walk() != nil {
130: 		return errors.New("DEMO_PRODUCT_REQUEST_INVALID")
131: 	}
132: 	if _, err := d.Token(); err != io.EOF {
133: 		return errors.New("DEMO_PRODUCT_REQUEST_INVALID")
134: 	}
135: 	var fields map[string]json.RawMessage
136: 	if json.Unmarshal(raw, &fields) != nil || fields == nil {
137: 		return errors.New("DEMO_PRODUCT_REQUEST_INVALID")
138: 	}
139: 	kind := reflect.TypeOf(target).Elem()
140: 	allowed := map[string]bool{}
141: 	for i := 0; i < kind.NumField(); i++ {
142: 		allowed[strings.Split(kind.Field(i).Tag.Get("json"), ",")[0]] = true
143: 	}
144: 	for key, value := range fields {
145: 		if !allowed[key] || bytes.Equal(bytes.TrimSpace(value), []byte("null")) {
146: 			return errors.New("DEMO_PRODUCT_REQUEST_INVALID")
147: 		}
148: 	}
149: 	d = json.NewDecoder(bytes.NewReader(raw))
150: 	d.DisallowUnknownFields()
151: 	if d.Decode(target) != nil || d.Decode(new(interface{})) != io.EOF {
152: 		return errors.New("DEMO_PRODUCT_REQUEST_INVALID")
153: 	}
154: 	return nil
155: }
156: func productUTC(s string) (time.Time, error) {
157: 	t, e := time.Parse("2006-01-02T15:04:05Z", s)
158: 	if e != nil || t.Format("2006-01-02T15:04:05Z") != s {
159: 		return time.Time{}, errors.New("DEMO_PRODUCT_TIME_INVALID")
160: 	}
161: 	return t, nil
