180: 	if !readyDigest.MatchString(d.ReadyDigest) || !readyDigest.MatchString(d.CandidateDigest) || !readyDigest.MatchString(d.ResultDigest) || !readyText(d.SourceRevision) {
181: 		return d, "", errors.New("DEMO_PRODUCT_REQUEST_INVALID")
182: 	}
183: 	if d.Action != "accept" && d.Action != "extend" || d.Action == "accept" && d.ExtensionSeconds != nil || d.Action == "extend" && (d.ExtensionSeconds == nil || *d.ExtensionSeconds < 1 || *d.ExtensionSeconds > maximumDemoRetentionSeconds) {
184: 		return d, "", errors.New("DEMO_PRODUCT_REQUEST_INVALID")
185: 	}
186: 	issued, ie := productUTC(d.IssuedAt)
187: 	expires, ee := productUTC(d.ExpiresAt)
188: 	if ie != nil || ee != nil || !expires.After(issued) || expires.Sub(issued) > 5*time.Minute {
189: 		return d, "", errors.New("DEMO_PRODUCT_TIME_INVALID")
190: 	}
191: 	if _, e = time.Parse(time.RFC3339Nano, d.ExpectedExpiry); e != nil {
192: 		return d, "", errors.New("DEMO_PRODUCT_TIME_INVALID")
