213: func productDeadline(item *lease, base time.Time) time.Time {
214: 	state := objectValue(item.Status["demoProduct"])
215: 	ready := objectValue(item.Status["demoReadiness"])
216: 	if state["leaseUID"] != item.Metadata.UID || state["readyDigest"] != ready["requestDigest"] {
217: 		return base
218: 	}
219: 	// List-map storage may reorder entries. Follow exact expiry links, not array order.
220: 	original := base
221: 	links := map[string]time.Time{}
222: 	for _, record := range productRecords(item) {
223: 		r := objectValue(record)
224: 		if r["action"] != "extend" {
225: 			continue
226: 		}
227: 		previous, e := time.Parse(time.RFC3339Nano, stringValue(r["previousExpiry"]))
228: 		next, ne := time.Parse(time.RFC3339Nano, stringValue(r["expiresAt"]))
229: 		if e != nil || ne != nil || !next.After(previous) {
230: 			return original
231: 		}
232: 		key := previous.UTC().Format(time.RFC3339Nano)
233: 		if _, exists := links[key]; exists {
234: 			return original
235: 		}
236: 		links[key] = next
237: 	}
238: 	for len(links) > 0 {
239: 		key := base.UTC().Format(time.RFC3339Nano)
240: 		next, exists := links[key]
241: 		if !exists {
242: 			return original
243: 		}
244: 		delete(links, key)
245: 		base = next
246: 	}
247: 
248: 	return base
249: }
