310: 		var apiErr *apiError
311: 		if errors.As(err, &apiErr) && apiErr.statusCode == 409 {
312: 			return nil, errors.New("DEMO_PRODUCT_VERSION_CONFLICT")
313: 		}
314: 		return nil, errors.New("DEMO_PRODUCT_COMMIT_UNCERTAIN")
315: 	}
316: 	var persisted lease
317: 	if c.kube(ctx, http.MethodGet, c.leasePath(d.LeaseName), nil, "application/json", &persisted) != nil || persisted.Metadata.UID != d.LeaseUID {
318: 		return nil, errors.New("DEMO_PRODUCT_COMMIT_UNCERTAIN")
319: 	}
320: 	actual, e := productReceipt(&persisted, d.DecisionID, digest)
321: 	if e != nil || actual == nil {
322: 		return nil, errors.New("DEMO_PRODUCT_COMMIT_UNCERTAIN")
323: 	}
324: 	a, _ := json.Marshal(actual)
325: 	b, _ := json.Marshal(receipt)
326: 	if !bytes.Equal(a, b) {
327: 		return nil, errors.New("DEMO_PRODUCT_COMMIT_UNCERTAIN")
328: 	}
329: 	return actual, nil
330: }
