332: func (c *controller) productHandler(w http.ResponseWriter, r *http.Request) {
333: 	w.Header().Set("Content-Type", "application/json")
334: 	w.Header().Set("Cache-Control", "no-store")
335: 	if c.product == nil || r.Method != http.MethodPost || (r.URL.Path != "/v1/demo-product/subjects" && r.URL.Path != "/v1/demo-product/decisions" && r.URL.Path != "/v1/demo-product/status") {
336: 		http.Error(w, "DEMO_PRODUCT_DISABLED_OR_ROUTE_INVALID", 404)
337: 		return
338: 	}
339: 	ctx, cancel := context.WithTimeout(r.Context(), 15*time.Second)
340: 	defer cancel()
341: 	if c.authenticateTransport(ctx, r.Header.Get("Authorization"), &readinessConfig{Audience: c.product.Audience, Producer: c.product.Producer}) != nil {
342: 		http.Error(w, "DEMO_PRODUCT_UNAUTHORIZED", 401)
343: 		return
344: 	}
345: 	raw, err := io.ReadAll(http.MaxBytesReader(w, r.Body, 16384))
346: 	if err != nil {
347: 		http.Error(w, "DEMO_PRODUCT_REQUEST_INVALID", 400)
348: 		return
349: 	}
350: 	var result interface{}
351: 	switch r.URL.Path {
352: 	case "/v1/demo-product/decisions":
353: 		var envelope productEnvelope
354: 		if err = productJSON(raw, &envelope); err == nil {
355: 			result, err = c.commitProduct(ctx, envelope)
356: 		}
357: 	case "/v1/demo-product/subjects":
358: 		var input struct {
359: 			SchemaVersion string `json:"schemaVersion"`
360: 			LeaseName     string `json:"leaseName,omitempty"`
361: 		}
362: 		err = productJSON(raw, &input)
363: 		if err == nil && (input.SchemaVersion != "demo-product-subject-request.v1" || input.LeaseName != "" && !readyName.MatchString(input.LeaseName)) {
364: 			err = errors.New("DEMO_PRODUCT_REQUEST_INVALID")
365: 		}
366: 		if err == nil {
367: 			var list leaseList
368: 			if input.LeaseName != "" {
369: 				var item lease
370: 				err = c.kube(ctx, http.MethodGet, c.leasePath(input.LeaseName), nil, "application/json", &item)
371: 				list.Items = []lease{item}
372: 			} else {
373: 				err = c.kube(ctx, http.MethodGet, c.leasePath(""), nil, "application/json", &list)
374: 			}
375: 			subjects := []map[string]interface{}{}
376: 			if err == nil {
377: 				for i := range list.Items {
378: 					subject, e := c.productSubject(ctx, &list.Items[i])
379: 					if e == nil {
380: 						subjects = append(subjects, subject)
381: 					} else if input.LeaseName != "" {
382: 						err = e
383: 					}
384: 				}
385: 			}
386: 			result = map[string]interface{}{"schemaVersion": "demo-product-subjects.v1", "subjects": subjects}
387: 		}
388: 	case "/v1/demo-product/status":
389: 		var input struct {
390: 			SchemaVersion string `json:"schemaVersion"`
391: 			DecisionID    string `json:"decisionId"`
392: 			LeaseName     string `json:"leaseName"`
393: 			LeaseUID      string `json:"leaseUID"`
394: 			PayloadDigest string `json:"payloadDigest"`
395: 		}
396: 		err = productJSON(raw, &input)
397: 		if err == nil && (input.SchemaVersion != "demo-product-status-request.v1" || !readyName.MatchString(input.LeaseName) || !readyText(input.LeaseUID) || !productDecisionID.MatchString(input.DecisionID) || !readyDigest.MatchString(input.PayloadDigest)) {
398: 			err = errors.New("DEMO_PRODUCT_REQUEST_INVALID")
399: 		}
400: 		if err == nil {
401: 			var item lease
402: 			err = c.kube(ctx, http.MethodGet, c.leasePath(input.LeaseName), nil, "application/json", &item)
403: 			if err == nil {
404: 				if item.Metadata.UID != input.LeaseUID {
405: 					err = errors.New("DEMO_PRODUCT_NOT_CURRENT")
406: 				} else {
407: 					var receipt map[string]interface{}
408: 					receipt, err = productReceipt(&item, input.DecisionID, input.PayloadDigest)
409: 					result = receipt
410: 					if receipt == nil && err == nil {
411: 						err = errors.New("DEMO_PRODUCT_DECISION_NOT_FOUND")
412: 					}
413: 				}
414: 			}
415: 		}
416: 	}
417: 	if err != nil {
418: 		code := err.Error()
419: 		if !strings.HasPrefix(code, "DEMO_PRODUCT_") {
420: 			code = "DEMO_PRODUCT_EVIDENCE_UNAVAILABLE"
421: 		}
422: 		http.Error(w, code, 409)
423: 		return
424: 	}
425: 	_ = json.NewEncoder(w).Encode(result)
426: }

